```tsx
import type { ReactElement } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps): ReactElement | null {
  if (text.length === 0) {
    return null;
  }

  return (
    <div
      className="status-message"
      role="status"
      aria-live="polite"
      aria-atomic="true"
    >
      <p className="status-message__text">{text}</p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
```

