.status-message {
  display: flex;
  align-items: center;
  gap: 0.75em;
  padding: 0.5em 0.5em 0.5em 1em;
  border-radius: 12px;
  border-left: 3px solid var(--myelin);
  background: var(--myelin-wash);
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1rem);
  animation: status-message-in 180ms ease-out both;
}

.status-message__text {
  flex: 1;
  min-width: 0;
  margin: 0;
}

.status-message__dismiss {
  font: inherit;
  font-size: 0.9em;
  min-height: 2.75rem;
  padding: 0.3em 1em;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: border-color 150ms ease, color 150ms ease;
}

.status-message__dismiss:hover {
  border-color: var(--myelin);
  color: var(--myelin);
}

.status-message__dismiss:focus-visible {
  border-color: var(--myelin);
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message,
:root[data-motion="reduce"] .status-message__dismiss {
  animation: none;
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message,
  .status-message__dismiss {
    animation: none;
    transition: none;
  }
}
